(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zzv-sj-prepa-chir-j9-ide3"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zzv-sj-prepa-chir-j9-ide3\",\n \"titre\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 58,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J9_Chirurgie_IDE3_corrige_explique.pdf\",\n   \"sha256\": \"d6136fd47e375a3255ad8af1663e2dace9ae115e73869e2e440c10876dc9ebb8\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J9 (IDE3)\",\n     \"slug\": \"prepa-chir-j9-ide3\",\n     \"pages\": \"\",\n     \"count\": 58,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le Glasgow est inférieur ou égal à 9 dans le traumatisme crânien grave\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le TC grave correspond à un Glasgow de 3 à 8, c'est-à-dire INFÉRIEUR à 9. Un Glasgow égal à 9 correspond déjà au TC modéré (9 à 12). « Inférieur ou égal à 9 » est donc faux.\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, niveaux de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le déficit moteur représente un critère d'appel au réanimateur en cas de traumatisme modéré\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours cite le déficit moteur parmi les critères d'appel au réanimateur dans le paragraphe du traumatisme crânien GRAVE (avec plaies crânio-cérébrales, convulsions, PCI associée à une lésion à risque hémorragique). Remarque : Les traumatismes modérés relèvent eux aussi de la réanimation selon le cours ; la nuance porte sur la liste des « critères d'appel », rattachée au TC grave.\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens (TC grave, critères d'appel au réanimateur)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'ostéosynthèse à foyer fermé, les plaques sont mises à distance de la fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'ostéosynthèse à foyer fermé, le matériel est mis en place par voie percutanée, à distance de la fracture, sans exposer le foyer. Remarque : Le cours cite pour le foyer fermé des vis, broches ou clous centromédullaires ; il ne parle pas de plaques.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Fractures de l'humérus, V. Traitement (méthodes chirurgicales)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La prostate est un organe masculin ou une petite glande génitale située sous la vessie et qui entoure la partie initiale de l'urètre.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours le dit presque mot pour mot : « La prostate est un organe ou petite glande génitale, masculin. Elle est située sous la vessie et entoure la partie initiale de l'urètre. »\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Adénome de la prostate, II. Physiopathologie\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le craquement est signe physique du traumatisme du bassin\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le craquement est un signe FONCTIONNEL du traumatisme du bassin (ressenti par le blessé), avec la douleur vive et l'impotence. Les signes physiques sont les déformations, hématomes, ecchymoses et les points douloureux.\\n\\nSource : Traumatologie Complet-2.pdf, Traumatismes du bassin, 2.1 Signes fonctionnels et 2.2 Signes physiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de la sonnette est la palpation qui déclenche souvent une douleur en regard des massifs articulaires postérieurs\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La pression déclenche souvent une douleur en regard des massifs articulaires postérieurs : c'est le signe de la sonnette.\\n\\nSource : Neurochorurgie.pdf, Sciatalgies / hernie discale, signes physiques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La commotion cérébrale est un épanchement sanguin intracrânien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La commotion cérébrale est « une altération fonctionnelle sans lésions matérielles du tissu de l'encéphale ». L'épanchement de sang intracrânien correspond aux hématomes et aux hémorragies.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatismes crâniens, IV-C Lésions cérébro-méningées\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'articulation de la hanche joue à la fois un rôle statique et un rôle dynamique\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La hanche est une énarthrose solide et mobile.\\n\\nSource : ARTHROLOGIE COMPLET.pdf, Articulation de la hanche (généralités et physiologie) ; ANATOMIE LIVRE 2023-2024 OK.pdf\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'irrigation vésicale bien conduite dans l'adénomectomie prévient les infections et les rétentions urinaires post opératoires\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Après adénomectomie, l'irrigation (lavage) vésicale continue empêche la formation de caillots qui boucheraient la sonde (rétention) ; elle accompagne la prévention de l'infection.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Adénome de la prostate, interventions infirmières (24 premières heures)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La science qui étudie seulement les fractures du crâne est la neurochirurgie.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La neurochirurgie traite toutes les lésions chirurgicales du système nerveux (crâne, encéphale, rachis, moelle, hernie discale…), pas seulement les fractures du crâne.\\n\\nSource : Neurochorurgie.pdf (sommaire : traumatismes crâniens, fractures du rachis, hernie discale, mal de Pott)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La glande à sécrétion amphicrine est le pancréas\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le pancréas est une glande mixte (amphicrine) : sécrétion externe (suc pancréatique par les acini) et sécrétion interne (insuline et glucagon par les îlots de Langerhans).\\n\\nSource : PDF HISTOLOGIE 2024.pdf, glandes mixtes ou amphicrines ; PDF GLANDE ENDOCRINE.pdf, pancréas\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'un des signes physiques de la gangrène gazeuse est la crépitation neigeuse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"À la palpation, une sensation de crépitation neigeuse sous-cutanée traduit l'emphysème (gaz dans les tissus).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Gangrène gazeuse, 4.1 Signes physiques (palpation)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'apparition du syndrome de wolkmann est uniquement liée à une défaillance de la surveillance infirmière.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le syndrome de Volkmann résulte d'une double faute thérapeutique : plâtre trop serré ET absence de surveillance des doigts. Il complique aussi certaines fractures elles-mêmes (coude, avant-bras de l'enfant).\\n\\nSource : Traumatologie Complet-2.pdf, Fracture de Pouteau-Colles, 1.5.2 Complications secondaires ; Syndrome de Wolkmann\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'intervalle libre a une durée plus courte dans l'hématome extradural que dans l'hématome intradural\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'hématome intradural « se distingue de l'hématome extradural par la grande durée de l'intervalle libre ». L'intervalle libre est donc plus court dans l'extradural.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatismes crâniens, VI-2 Hématome intradural\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La respiration paradoxale s'observe uniquement dans le volet costal\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La respiration paradoxale est la conséquence typique du volet costal ; d'autres atteintes de la paroi thoracique peuvent aussi en donner. (explication hors cours du projet) pour le mot « uniquement ».\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Traumatisme du thorax (volet costal)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"En cas de subluxation, les deux (02) surfaces articulaires sont en rupture permanente.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans la subluxation, un contact partiel persiste entre les surfaces articulaires (luxation incomplète). La perte de contact permanente et complète définit la luxation complète.\\n\\nSource : Traumatologie Complet-2.pdf, Généralités sur les luxations ; Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf) (« s'il reste un contact partiel, il s'agit d'une subluxation »)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La néphrectomie est un examen radiologique du rein\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La néphrectomie est l'ablation chirurgicale du rein (le cours parle de néphrectomie élargie dans le cancer du rein). Ce n'est pas un examen radiologique.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Cancer du rein, IV. Traitement\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le myosis et la mydriase sont des effets similaires du système neurovégétatif sur l'œil\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ces effets sont opposés : le sympathique dilate la pupille (mydriase), le parasympathique la contracte (myosis).\\n\\nSource : SYSTÈME NERVEUX COMPLET.pdf, actions du sympathique et du parasympathique ; ANATOMIE LIVRE 2023-2024 OK.pdf, tableau des actions du système végétatif\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la recherche de la hanche luxée chez le nourrisson, le signe de NELATON est « positif » lorsque les deux cuisses sont fléchies et que les genoux sont au même niveau.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans la luxation congénitale de la hanche, le signe de Nélaton est positif quand, les deux cuisses fléchies, les genoux NE sont PAS au même niveau.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Malformations congénitales des membres, 3.5 Hanche luxée\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La température, le pouls et la TA font partie des éléments de la surveillance dans la phlébothrombose.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au 2e jour post-opératoire, on surveille les constantes (TA, FR, pouls, température) et on pense à une phlébothrombose.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.2.2 Surveillance des constantes II. QCM / QRU\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les éléments de surveillance du post-opératoire immédiat ci-dessous, deux appartiennent à la fonction neurologique. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Audition\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Chaleur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cyanose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déglutition\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pression artérielle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Audition ; D. Déglutition\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Pour l'état de conscience, le cours prévoit de vérifier les réponses aux excitations auditives (appeler le patient) et la déglutition.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.2 Surveiller l'état de conscience\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La pression artérielle fait partie de la surveillance\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Digestive\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Neurologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hémodynamique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ostéoarticulaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Hémodynamique\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La pression artérielle fait partie de la surveillance hémodynamique (circulatoire), comme le pouls.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.1 Surveiller les fonctions vitales (dépister un choc)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments ci-dessous relèvent de la surveillance infirmière d'un plâtre, sauf deux. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Durée du plâtre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleurs sous plâtre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Extrémités cyanosées\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ablation du plâtre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dysesthésie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Extrémités froides\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Durée du plâtre ; D. Ablation du plâtre\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"La surveillance du plâtre porte sur les signes de compression : douleurs, cyanose, froideur, troubles de la sensibilité (dysesthésie). La durée du plâtre et son ablation ne sont pas des éléments de surveillance.\\n\\nSource : Traumatologie Complet-2.pdf, Rôle de l'infirmier dans la surveillance du plâtre (7.1) ; Fracture de Pouteau-Colles (1.4)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le centre respiratoire principal est situé dans le\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cervelet\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Bulbe rachidien\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Thalamus\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hypophyse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Bulbe rachidien\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"« Les centres nerveux respiratoires principaux sont situés dans le bulbe. »\\n\\nSource : PDF APPAREIL RESPIRATOIRE 2023 SF IDE.pdf, mécanique respiratoire (centres respiratoires)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture de Pouteau-Colles est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une fracture de l'épiphyse supérieure du fémur\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une fracture de l'épiphyse supérieure du radius\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une fracture de l'épiphyse inférieure du radius\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une fracture de l'épiphyse inférieure du fémur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Une fracture de l'épiphyse inférieure du radius\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La fracture de Pouteau-Colles est une fracture de l'extrémité inférieure (distale) du radius.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures du poignet, I. Fracture de Pouteau-Colles\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les déplacements des fractures ci-dessous, la forme comminutive correspond à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une fragmentation multiple de l'os\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une Rotation des fragments de l'os\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un chevauchement des fragments de l'os\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une angulation des fragments de l'os\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une fragmentation multiple de l'os\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Si le choc est très violent, l'os se fracture en plusieurs endroits : fracture comminutive. Rotation, chevauchement et angulation sont des déplacements.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Généralités sur les fractures, 4.1 et 4.2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la surveillance post-opératoire trois (3) des éléments ci-dessous recherchent un choc hémodynamique. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Téguments (Coloration)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déglutition\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pouls\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Douleur\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Conscience\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Faciès\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Pouls ; E. Conscience ; F. Faciès\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Pour dépister un choc post-opératoire, on surveille notamment le pouls, le faciès et l'état de conscience. Remarque : Le cours cite aussi la coloration et la chaleur de la peau parmi les éléments qui dépistent un choc.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.1 Surveiller les fonctions vitales ; Chocs traumatiques (premiers signes d'une insuffisance circulatoire)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la surveillance du post-opératoire immédiat, trois apprécient la fonction neurologique. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Coloration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Conscience\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faciès\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déglutition\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pression artérielle\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Audition\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Conscience ; D. Déglutition ; F. Audition\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Surveillance de la fonction neurologique : état de conscience, déglutition et réponse aux stimulations auditives (audition).\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.2 Surveiller l'état de conscience\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une perte totale de la sensibilité est appelée\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypoesthésie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Anesthésie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Myosis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Paresthésie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Anesthésie\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La perte totale de la sensibilité est l'anesthésie. L'hypoesthésie en est une diminution ; la paresthésie est une sensation anormale.\\n\\nSource : Neurochorurgie.pdf, Fracture du rachis (examen sensitif : hypoesthésie, anesthésie)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'une des étiologies de l'occlusion intestinale d'origine fonctionnelles est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'invagination\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La tumeur mésentérique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La tumeur intestinale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La tumeur mésentérique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Parmi les causes des troubles moteurs de l'occlusion fonctionnelle, le cours cite la proximité d'un foyer purulent, d'un hématome rétropéritonéal ou d'une tumeur mésentérique. L'invagination et la tumeur intestinale sont des causes mécaniques.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Occlusions intestinales aiguës, 1.2 Occlusions fonctionnelles\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la surveillance postopératoire immédiate d'un opéré de péritonite, un des soins ci-dessous est à exécuter par l'infirmier. Lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prévenir les nausées et vomissements par des antiémétiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Restaurer les pertes hydriques et caloriques par voie veineuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rassurer le client et exécuter la prémédication prescrite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Restaurer les pertes hydriques et caloriques par voie veineuse\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Après l'opération d'une péritonite : « Restaurer les pertes d'eau, d'électrolytes, de calories, par voie veineuse jusqu'au rétablissement du transit. » Rassurer et faire la prémédication sont des soins préopératoires.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Péritonites, VIII. Interventions infirmières\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic présomptif d'une tuméfaction indolente, du scrotum de taille moyenne avec une épreuve de la lampe torche positive, est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La hernie inguino-scrotale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La tumeur du scrotum\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'hydrocèle vaginale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. L'hydrocèle vaginale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Tuméfaction indolente, transparente à la transillumination (lampe torche) : c'est l'hydrocèle vaginale.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Hydrocèle, IV. Clinique (4-3)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le gargouillement perçu à la réduction d'une hernie suspecte un encastrement:\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De l'épiploon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De l'intestin\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De fécalome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. De l'intestin\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"« Un gargouillement à la réduction indique la présence d'intestin dans le sac herniaire. » La sonorité ou la matité orientent vers l'épiploon.\\n\\nSource : Cours de chirurgie traumatique et digestif.pptx, Hernies, IV. Manifestations cliniques\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La crise appendiculaire a pour diagnostic différentiel deux (2) des pathologies ci-dessous\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Grossesse extra-utérine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hydrocèle vaginale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Torsion testiculaire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hernie étranglée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rate paludéenne\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Disjonction symphysaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Grossesse extra-utérine ; D. Hernie étranglée\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"Le diagnostic différentiel de l'appendicite comprend notamment la grossesse extra-utérine (rupture d'une grossesse tubaire) et la hernie étranglée.\\n\\nSource : Cours L2 IDE « Prise en charge infirmière des pathologies chirurgicales » (licence 2 ide.pdf), Appendicite aiguë, VIII. Diagnostic différentiel ; Cours de chirurgie traumatique et digestif.pptx, VIII\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments ci-après de la surveillance du post-opératoire immédiat recherchent un choc hémodynamique, sauf deux. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Coloration de la peau\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleur\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faciès\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Pression artérielle\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Conscience\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Pouls\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Coloration de la peau ; B. Douleur\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"La douleur et la coloration de la peau ne figurent pas, selon la correction nationale, parmi les éléments qui recherchent un choc.\\n\\nSource : Traumatologie Complet-2.pdf, 8.2.4.1.1 Surveiller les fonctions vitales\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": null,\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments de la surveillance infirmière ci-dessous relèvent de l'état végétatif du patient : Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Mouvement respiratoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réponse verbale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Mouvement orienté\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rythme cardiaque\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Diurèse horaire\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Degré de douleur\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Mouvement respiratoire ; D. Rythme cardiaque\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\"\n       ],\n       \"explanation\": \"L'état végétatif se surveille par le pouls, la tension artérielle, le rythme cardiaque et respiratoire. Réponse verbale et mouvement orienté relèvent de l'état neurologique.\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, 4.5 Soins post-opératoires III. CAS CLINIQUE\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__36\",\n       \"num\": \"37\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Deux (02) points douloureux sont recherchés à la palpation douce du bassin de ce patient ; lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Iléon\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Périnée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pubis\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Crête iliaque\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Vertèbre lombaire 5\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Pubis ; D. Crête iliaque\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"À la palpation douce du bassin, on recherche des points douloureux dans la région pubis – crête iliaque et au niveau de l'articulation sacro-iliaque.\\n\\nSource : Traumatologie Complet-2.pdf, Traumatismes du bassin, 2.2.2 Palpation\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__37\",\n       \"num\": \"38\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Les membres de l'équipe médicale des sapeurs-pompiers ont eu à observer deux (02) gestes dans la prise en charge de M. KOLA afin d'éviter d'aggraver son pronostic vital ; lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Transport du blessé allongé sur le siège\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ramassage du blessé en bloc rigide\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Transport du blessé le plus rapidement possible\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Transport du blessé sur un plan dur en décubitus dorsal ou latéral\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ramassage du blessé en décubitus ventral\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Ramassage du blessé en bloc rigide ; D. Transport du blessé sur un plan dur en décubitus dorsal ou latéral\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Pour ne pas aggraver le pronostic, le blessé est relevé et transporté en monobloc, axe tête-cou-tronc en rectitude, sur un plan dur en décubitus dorsal (ou latéral de sécurité).\\n\\nSource : Traumatologie Complet-2.pdf, Conduite à tenir auprès d'un traumatisé des voies publiques, II. Gestes salvateurs ; Neurochorurgie.pdf (déplacement en monobloc)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__38\",\n       \"num\": \"39\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Deux (02) autres gestes sont à proscrire sur les lieux de l'accident dans la prise en charge de ce blessé ; lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La précipitation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'usage du brancard\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le dégagement du blessé en traction axiale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'installation du blessé bouche en position déclive\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'empoigne sous les aisselles\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. La précipitation ; E. L'empoigne sous les aisselles\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Gestes à proscrire : la précipitation et l'empoigne sous les aisselles. Le brancard et la traction axiale sont au contraire des gestes salvateurs.\\n\\nSource : Traumatologie Complet-2.pdf, Conduite à tenir auprès d'un traumatisé des voies publiques, I. Gestes à proscrire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__39\",\n       \"num\": \"40\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"KOLA fait un choc traumatique malgré les moyens médicaux déployés après son admission dans le service des urgences chirurgicales. Indiquer une autre variété de choc traumatique parmi les propositions ci-dessous :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"40. Indiquer une autre variété de choc traumatique parmi les propositions ci-dessous :\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"A. Choc cardiogénique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"B. Choc hypovolémique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"C. Choc opératoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. C. Choc opératoire\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"« Choc opératoire est une variété de choc traumatique. » Les chocs cardiogénique et hypovolémique ont d'autres causes. Remarque : Dans le sujet, le premier bouton reprend le texte de la question (« 40. Indiquer… ») ; ce n'est pas une vraie proposition. Remarque : Dans le sujet, le premier bouton reprend le texte de la question (« 40. Indiquer… ») ; ce n'est pas une vraie proposition.\\n\\nSource : Traumatologie Complet-2.pdf, Chocs traumatiques, II. Étiologies\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__40\",\n       \"num\": \"41\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"L'état de choc est : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une incapacité de l'appareil circulatoire à assurer le flux sanguin et donc l'apport d'oxygène nécessaire aux tissus de l'organisme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La soudaine inefficacité de la pompe cardiaque qui entraine une chute brutale du débit cardiaque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Un syndrome général de plus ou moins grande gravité observée après toute agression de l'organisme quelle que soit sa nature.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une incapacité de l'appareil circulatoire à assurer le flux sanguin et donc l'apport d'oxygène nécessaire aux tissus de l'organisme\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"« L'état de choc, ou insuffisance circulatoire, peut se définir comme une incapacité de l'appareil circulatoire à assurer le flux sanguin et donc l'apport d'oxygène nécessaire aux tissus. » B définit le choc cardiogénique, C le choc au sens général.\\n\\nSource : Traumatologie Complet-2.pdf, Chocs traumatiques, I. Définition\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__41\",\n       \"num\": \"42\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Enoncer deux (02) premiers signes d'une insuffisance circulatoire dans la surveillance de ce blessé choqué :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hématome\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémarthrose\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fréquence cardiaque\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tuméfaction\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Etat de conscience\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Fréquence cardiaque ; E. Etat de conscience\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Premiers signes d'insuffisance circulatoire : température, fréquence cardiaque, pression artérielle, coloration cutanée, diurèse, état de conscience, état respiratoire.\\n\\nSource : Traumatologie Complet-2.pdf, Chocs traumatiques, V. Surveillance d'un patient choqué\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__42\",\n       \"num\": \"43\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Enumérer trois (03) besoins fondamentaux prioritaires chez M. KOLA polytraumatisé étant dans le coma parmi les propositions ci-dessous indiquées\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Besoin de manger et boire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Besoin d'être propre, soigné et protéger ses téguments\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Besoin de respirer\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Besoin d'éliminer les déchets biologiques\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Besoin d'éviter les dangers\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Besoin d'être propre, soigné et protéger ses téguments ; C. Besoin de respirer ; E. Besoin d'éviter les dangers\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Chez un polytraumatisé comateux, les besoins prioritaires sont de respirer, d'éviter les dangers (sécurité) et d'être propre et de protéger ses téguments (escarres). Manger, boire et éliminer sont assurés par sondes et perfusions. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__43\",\n       \"num\": \"44\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\",\n       \"text\": \"Quel est le diagnostic infirmier en rapport avec la fonction locomotrice parmi ceux énumérés ci-dessous ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Difficulté due au polytraumatisme reliée à l'altération du système locomoteur.\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Incapacité due à son polytraumatisme l'empêchant se mobiliser\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Impossibilité due à l'altération du système locomoteur reliée à son polytraumatisme\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Impossibilité due à l'altération du système locomoteur reliée à son polytraumatisme\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le diagnostic infirmier relie un problème (impossibilité de se mobiliser) à sa cause (altération du système locomoteur) liée au polytraumatisme. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__44\",\n       \"num\": \"45\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Vous disposez les dérivés érythrocytaires à votre niveau. Indiquer la quantité de sang nécessaire à la transfusion de M. KOLA.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"750 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1500 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"1000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"500 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 750 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Δ Hb = 10 − 5 = 5 g/dl, poids 50 kg. Culot globulaire = 5 × 50 × 3 = 750 ml. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__45\",\n       \"num\": \"46\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Le débit de cette transfusion, si tout le sang doit passer en 4h et demi est de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"41 gttes/mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"42 gttes/mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"41,66 gttes/mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 42 gttes/mn\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"750 ml × 15 gouttes / 270 min (4 h 30) = 41,66 gouttes/min, arrondi à 42 gouttes/min. (explication hors cours du projet) Remarque : On ne règle pas un débit en fraction de goutte : la correction nationale retient l'arrondi (42), pas la valeur exacte (41,66).\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__46\",\n       \"num\": \"47\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"La fracture du crâne a occasionné un dysfonctionnement cérébral (commotion cérébrale) chez M. KOLA. Relever les deux (02) éléments de l'ouverture des yeux consécutifs à l'examen neurologique de ce blessé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Adaptée, orientée à la douleur 5\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Spontanée 4\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Volontaire sur commande 6\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Appropriée 5\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"A la douleur 2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Spontanée 4 ; E. A la douleur 2\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Ouverture des yeux : spontanée = 4, à l'appel = 3, à la douleur = 2, nulle = 1. « Adaptée/orientée à la douleur 5 » et « volontaire 6 » sont des cotations motrices ; « appropriée 5 » est verbale.\\n\\nSource : NEUROCHIRURGIE L3.pptx, score de Glasgow\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__47\",\n       \"num\": \"48\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"On parle de traumatisme crânien grave lorsque le Glasgow est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"≤ 9\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"= 9\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"< 9\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. < 9\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Traumatisme crânien grave : Glasgow inférieur à 9 (3 à 8) après correction des fonctions vitales.\\n\\nSource : Neurochorurgie.pdf, Traumatismes crâniens, niveaux de gravité\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__48\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Dans le traumatisme crânien sans perte de connaissance initiale (PCI) ni amnésie, sans signe neurologique, avec CGS 15, sans facteur de risque, il : (cocher la bonne réponse)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faut d'emblée faire un scanner et une surveillance neurologique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Ne faut pas faire d'exploitation ni de surveillance neurologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Faut faire une surveillance neurologique de 24h et un scanner à la 6ème heure et faire la sortie du patient si scanner normal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Ne faut pas faire d'exploitation ni de surveillance neurologique\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Groupe 1 : TC sans PCI ni amnésie, sans signe neurologique, GCS 15, sans facteur de risque → pas d'exploration ni de surveillance. La proposition C correspond au groupe 2.\\n\\nSource : NEUROCHIRURGIE L3.pptx, Conduite à tenir, groupes 1 et 2\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__49\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Le stade de coma selon GLASGOW de M. KOLA polytraumatisé de la voie publique qui ouvre à la douleur, émet des mots inappropriés et fait une flexion du membre supérieur à la douleur de façon anormale est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Coma stade I\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Coma stade II\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Coma stade III\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Coma stade I\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Yeux à la douleur = 2 ; mots inappropriés = 3 ; flexion anormale = 3 ; Glasgow = 8 (TC grave). (explication hors cours du projet) pour la correspondance avec les stades du coma. Remarque : Le cours ne donne pas de correspondance entre le Glasgow et les « stades » I, II ou III du coma.\\n\\nSource : NEUROCHIRURGIE L3.pptx, score de Glasgow\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__50\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Quel est l'ordre normal des gestes à poser avant la pose d'une poche de sang ? 1. Envoyer l'AS à la recherche du sang 2. Vérifier la concordance de la poche de sang avec le sang prescrit 3. S'assurer que le malade n'a pas besoin urgent 4. Faire le test de compatibilité au lit du malade\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A (1, 2, 3, 4)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B (3, 1, 2, 4)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C (2, 1, 3, 4)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D (1, 3, 2, 4)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. C (2, 1, 3, 4)\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Ordre retenu : vérifier la concordance de la poche avec le sang prescrit, envoyer l'AS chercher le sang, s'assurer que le malade n'a pas de besoin urgent, puis faire le test de compatibilité au lit. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__51\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Lors de la pose de la transfusion sanguine, vous vous êtes piqué(e) avec l'aiguille non souillée par le sang. Que faites-vous à la suite de cette blessure ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Informer le major et arrêter le soin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faire saigner la plaie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nettoyer la plaie avec une solution antiseptique et continuer le soin\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire le test de VIH\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ne pas faire une déclaration d'AES chez le médecin référent.\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Demander à l'AS de vous suppléer dans le soin.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Nettoyer la plaie avec une solution antiseptique et continuer le soin ; E. Ne pas faire une déclaration d'AES chez le médecin référent.\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Avec une aiguille non souillée par le sang, la correction nationale retient : nettoyer la plaie à l'antiseptique, continuer le soin, sans déclaration d'AES. (explication hors cours du projet) Remarque : En dehors du cours : les protocoles AES recommandent en général de déclarer tout accident d'exposition ; la réponse E est à confirmer avec l'enseignant.\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__52\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Parmi les interventions infirmières énumérées ci-dessous, indiquer trois (03) qui relèvent des soins préopératoires :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prévention thrombo-embolique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Groupage sanguin + Rh\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Préparation psychologique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Apport nutritionnel par la réanimation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveillance et contrôle des drainages\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Vérification de la diète alimentaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Groupage sanguin + Rh ; C. Préparation psychologique ; F. Vérification de la diète alimentaire\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Soins préopératoires : prélèvements (groupe sanguin + Rh), préparation psychologique, vérifier que le malade est à jeun. Prévention thrombo-embolique, apport nutritionnel par la réanimation et surveillance des drains concernent surtout le post-opératoire.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de l'humérus, 6.2.1 Suivi préopératoire et 6.2.2 Suivi postopératoire\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__53\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Deux (02) complications sont immédiates parmi les complications suivantes des fractures du fémur ; lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accidents de décubitus\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Choc traumatique et hémorragique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Phlébite et embolie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Lésions vasculo-nerveuses\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Atrophie musculaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Choc traumatique et hémorragique ; D. Lésions vasculo-nerveuses\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Complications immédiates de la fracture du fémur : ouverture du foyer, choc traumatique et hémorragique, lésions vasculo-nerveuses. Phlébite et accidents de décubitus sont secondaires ; atrophie musculaire tardive.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de la diaphyse du fémur, V. Complications\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__54\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"La fracture du bassin a occasionné un globe vésical chez le patient, accompagné de douleurs et d'une urétrorragie. Ce patient présente probablement :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une rupture de l'urètre membraneux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une rupture extra péritonéale de la vessie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une rupture intra péritonéale de la vessie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Une rupture de l'urètre membraneux\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Lésion de l'urètre : rétention d'urine avec globe vésical et impossibilité d'uriner ; l'urétrorragie la confirme. La rupture de la vessie donne au contraire une absence de globe et une hématurie.\\n\\nSource : Traumatologie Complet-2.pdf, Traumatismes du bassin, 2.4.2.2 Complications immédiates ; Cours de chirurgie traumatique et digestif.pptx, complications urinaires (rupture de l'urètre membraneux)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__55\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Relever deux (02) conséquences de la complication immédiate d'une fracture ouverte parmi les éléments ci-dessous cités :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Infection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémorragie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inflammatoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Septicémie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Anémie ; E. Septicémie\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La complication immédiate de la fracture ouverte est l'ouverture du foyer avec hémorragie : elle entraîne anémie et risque infectieux généralisé (septicémie).\\n\\nSource : Traumatologie Complet-2.pdf, 8.1.2 Fractures ouvertes ; Pathologie chirurgicale – Sémiologie L1 (PATHOLOGIE CHIRUR-SEMIO L1), Septicémie (porte d'entrée cutanée)\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__56\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Dans la réalisation du pansement du patient KOLA opéré de sa fracture ouverte du fémur, vous constatez un lâchage des fils de suture très localisé, une plaie rouge œdématiée, un suintement de pus. De ces protocoles basés sur les gestes suivants, lequel convient ? 1. Information du chirurgien 2. Nettoyage de la plaie 3. Application d'antiseptique 4. Prélèvement de pus 5. Fermeture du pansement 6. Attente des prescriptions du chirurgien\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"A (1, 2, 3, 4)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"B (2, 3, 5, 1)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"C (2, 3, 4, 5, 6)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"D (4, 2, 3, 5, 1)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. D (4, 2, 3, 5, 1)\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Devant une plaie infectée (pus, lâchage des fils) : prélever le pus pour l'antibiogramme avant tout antiseptique, nettoyer, appliquer l'antiseptique, fermer le pansement, puis informer le chirurgien. (explication hors cours du projet)\\n\\nSource : —\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j9-ide3__57\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique — Vous êtes chargé de l'encadrement clinique des étudiants stagiaires de l'INFAS toutes promotions confondues. Au cours de votre garde de 24h, vous recevez en votre qualité de responsable des soins infirmiers du service des urgences chirurgicales du CHU où vous exercez M. KOLA 42 ans, 50kg polytraumatisé de la voie publique dans un état critique, évacué par les secours médicalisés des Sapeurs-pompiers qui étaient sur les lieux de l'accident pour les premiers soins. Avec le chirurgien, vous procédez à l'examen clinique de la victime, suivi d'une série d'examens radiologiques révélant : – Une fracture du bassin – Une fracture du 1/3 moyen de la dialyse du fémur avec grande ouverture – Une fracture du crâne\\n\\nCas clinique — Par rapport à la fracture du 1/3 moyen de la diaphyse du fémur avec grande ouverture, M. KOLA présente à la NFS un taux d'hémoglobine (TxHb) à 5g/dl de sang et le chirurgien décide de faire monter ce taux à 10g/dl avant l'intervention chirurgicale.\",\n       \"text\": \"Le bandage en huit (8) de chiffre est un traitement orthopédique utilisé en cas de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Luxation de l'épaule\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fracture des côtes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fracture de clavicule\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Fracture de clavicule\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le bandage en huit de chiffre (branches croisées dans le dos) est la contention orthopédique de la fracture de la clavicule.\\n\\nSource : Traumatologie Complet-2.pdf, Fractures de la clavicule, 6.1 Méthode orthopédique\",\n       \"sourceDoc\": \"Préparation D.E (J) · Chirurgie · Prépa D.E J9 (IDE3)\",\n       \"sourceFile\": \"J9_Chirurgie_IDE3_corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
